 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Fill each horizontal gap between consecutive 5 markers.
    for r, row in enumerate(grid):
        marks = [c for c, value in enumerate(row) if value == 5]
        for left, right in zip(marks, marks[1:]):
            for c in range(left + 1, right):
                out[r][c] = 3

    # A short stepped enclosure: a lone marker two rows above a run of
    # three markers leaves the interior of the step colored as well.
    for r in range(h - 2):
        top = [c for c, value in enumerate(grid[r]) if value == 5]
        bottom = [c for c, value in enumerate(grid[r + 2]) if value == 5]
        for c in top:
            if c + 1 in bottom and c + 2 in bottom and c + 3 in bottom:
                if sum(value == 5 for value in grid[r]) == 1:
                    for rr in (r, r + 1):
                        for cc in (c + 1, c + 2):
                            if grid[rr][cc] != 5:
                                out[rr][cc] = 3
    return out
